        return self.items.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    values = []
    for key in keys:
        try:
            values.append(self[key])
        except KeyError:
            pass
    return values

def data(self, *keys):
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self):
                raise IndexError("Index out of bounds")
            result[key] = self[key]
        else:
            result[key] = self.get(key, None)
    return result

def pop_u16(self):
    if len(self) < 2:
        raise ValueError("Not enough data to pop 16 bits")
    return (self.pop() << 8) | self.pop()

