def validate_fixity(self, fixity, manifest_files):
    # Check if fixity block is present
    if fixity is None:
        raise ValueError("Fixity block is missing")

    # Check if fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block is not a dictionary")

    # Check if fixity block has the required keys
    required_keys = ["algorithm", "digest"]
    for key in required_keys:
        if key not in fixity:
            raise ValueError(f"Fixity block is missing required key: {key}")

    # Check if algorithm is a supported algorithm
    algorithm = fixity["algorithm"]
    if algorithm not in SUPPORTED_ALGORITHMS:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    # Check if digest is a string
    digest = fixity["digest"]
    if not isinstance(digest, str):
        raise ValueError("Digest is not a string")

    # Check if digest is a valid hexadecimal string
    if not re.match(r"^[0-9a-fA-F]+$", digest):
        raise ValueError("Digest is not a valid hexadecimal string")

    # Check if digest length is correct
    if len(digest) != DIGEST_LENGTH:
        raise ValueError(f"Digest length is incorrect: {len(digest)}")

    # Check if all files in manifest are referenced in fixity block
    for file in manifest_files:
        if file not in fixity:
            raise ValueError(f"File {file} is not referenced in fixity block")

    # Check if all files in fixity block are in manifest
    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File {file} is not in manifest")

    # If all checks pass, return True
    return True

