def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None")

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("commands must be a list of strings")
        if not command.strip():
            raise ValueError("commands must not be empty")

    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("args must be a list of strings")
        if not arg.strip():
            raise ValueError("args must not be empty")

    if env is not None:
        for key, value in env.items():
            if not isinstance(key, str):
                raise ValueError("env keys must be strings")
            if not isinstance(value, str):
                raise ValueError("env values must be strings")

    try:
        if cwd is not None:
            os.chdir(cwd)
        if verbose:
            print("Running command:", " ".join(commands + args))
        if hide_stderr:
            with open(os.devnull, "w") as devnull:
                subprocess.run(commands + args, stdout=subprocess.PIPE, stderr=devnull, env=env)
        else:
            subprocess.run(commands + args, stdout=subprocess.PIPE, env=env)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Command failed with exit code {}: {}".format(e.returncode, " ".join(commands + args)))

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for obj in self.objects:
        num_objects += 1
        if validate_objects and not obj.is_valid():
            if show_warnings:
                print(f"Warning: Object {obj.name} is not valid.")
            continue
        if check_digests and not obj.check_digest():
            if show_warnings:
                print(f"Warning: Object {obj.name} has an invalid digest.")
            continue
        good_objects += 1
    return num_objects, good_objects

