def vertex3tuple(vertices):
    if not vertices:
        raise ValueError("vertices cannot be empty")
    if len(vertices) < 3:
        raise ValueError("vertices must have at least 3 elements")
    if not all(isinstance(vertex, tuple) and len(vertex) == 2 for vertex in vertices):
        raise ValueError("vertices must be a list of 2-tuples")

    result = []
    for i in range(len(vertices)):
        vertex = vertices[i]
        prev_vertex = vertices[(i - 1) % len(vertices)]
        next_vertex = vertices[(i + 1) % len(vertices)]
        result.append((vertex, prev_vertex, next_vertex))

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list of strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if number == 0:
        return alphabet[0]

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.zfill(padding)

    return result

