            setattr(self, field, getattr(self, field) * other)
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram")
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be a callable")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
    if not isinstance(field_names, tuple) or len(field_names) != hist.dimension:
        raise ValueError("field_names must be a tuple of length equal to the histogram dimension")
    if scale is not None and not isinstance(scale, bool):
        raise TypeError("scale must be a boolean")

    graph = Graph(field_names=field_names)
    for bin_ in hist.bins:
        if not isinstance(bin_, NumericBin):
            raise TypeError("hist must contain only numeric bins")
        if make_value is None:
            value = bin_.content
        else:
            value = make_value(bin_.content)
        if not isinstance(value, tuple) or len(value) != hist.dimension:
            raise ValueError("make_value must return a tuple of length equal to the histogram dimension")
        if get_coordinate == "left":
            coordinate = bin_.left
        elif get_coordinate == "right":
            coordinate = bin_.right
        else:
            coordinate = (bin_.left + bin_.right) / 2
        graph.add_point(coordinate, value)

    if scale is not None:
        graph.scale = hist.scale if scale else None

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if not tentative:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid("Candidate does not provide the interface")
        for name, method in iface.namesAndDescriptions():
            if name not in candidate:
                raise zope.interface.Invalid("Candidate does not define method {}".format(name))
            if not method.isSignatureCompatible(candidate[name]):
                raise zope.interface.Invalid("Method {} has an incompatible signature".format(name))
        for name, attribute in iface.namesAndDescriptions():
            if name not in candidate:
                raise zope.interface.Invalid("Candidate does not define attribute {}".format(name))
        return True
    except zope.interface.Invalid as e:
        raise e

