def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is required")

    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid spec content") from e

    if "name" not in spec_data:
        raise IRValidatorException("Name is missing in spec file")

    if "version" not in spec_data:
        raise IRValidatorException("Version is missing in spec file")

    if "description" not in spec_data:
        raise IRValidatorException("Description is missing in spec file")

    if "inputs" not in spec_data:
        raise IRValidatorException("Inputs are missing in spec file")

    if "outputs" not in spec_data:
        raise IRValidatorException("Outputs are missing in spec file")

    return spec_data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file must be provided")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException("YAML file not found")
    except yaml.YAMLError:
        raise IRValidatorException("Invalid YAML file")

    if not data:
        raise IRValidatorException("YAML file is empty")

    return data

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {}
    for arg in self.args:
        if arg.deprecated:
            deprecated_args[arg.name] = arg.deprecated
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    deprecated_args = []
    for arg in cli_args:
        if arg in answer_file_args:
            deprecated_args.append(arg)
    if deprecated_args:
        print("The following arguments are deprecated:", deprecated_args)

def get_silent_args(self, args):
    silenced_args = []
    for arg in args:
        if arg.startswith("-"):
            silenced_args.append(arg)
    return silenced_args

def validate_requires_args(self, args):
    if not args:
        raise ValueError("No arguments provided")
    for arg in args:
        if not arg:
            raise ValueError(f"Argument {arg} is required but not provided")

def validate_length_args(self, args):
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than the specified length {self.length}")

def validate_choices_args(self, args):
    for arg in args:
        if arg not in self.available_choices:
            raise ValueError(f"Invalid choice: {arg}")

def validate_min_max_args(self, args):
    if len(args) < 2:
        raise ValueError("Expected at least 2 arguments, but got {}".format(len(args)))
    if len(args) > 3:
        raise ValueError("Expected at most 3 arguments, but got {}".format(len(args)))
    if args[0] > args[1]:
        raise ValueError("First argument must be less than or equal to second argument")
    if len(args) == 3 and args[1] > args[2]:
        raise ValueError("Second argument must be less than or equal to third argument")

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    for arg in args:
        if arg.startswith("-"):
            control_args[arg] = args[arg]
        else:
            nested_args[arg] = args[arg]
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is not None:
        for key, value in extra_vars.items():
            vars_dict[key] = value
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    # Validate input parameters
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("ir_workspace must be an InfraredWorkspace object")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("ir_plugin must be an InfraredPlugin object")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose must be an integer")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dictionary")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dictionary")

    # Build the Ansible command
    ansible_cmd = ["ansible-playbook", playbook_path]
    if verbose is not None:
        ansible_cmd.append("-v")
        ansible_cmd.append(str(verbose))
    if extra_vars is not None:
        for key, value in extra_vars.items():
            ansible_cmd.append("-e")
            ansible_cmd.append(f"{key}={value}")
    if ansible_args is not None:
        for key, value in ansible_args.items():
            ansible_cmd.append("-e")
            ansible_cmd.append(f"{key}={value}")

    # Run the Ansible command
    try:
        subprocess.run(ansible_cmd, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible command failed with exit code {e.returncode}")

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        # Validate input parameters
        if not isinstance(cli_args, list):
            raise ValueError("cli_args must be a list")
        if not isinstance(vars_dict, dict):
            raise ValueError("vars_dict must be a dict")
        if not isinstance(ir_workspace, InfraredWorkspace):
            raise ValueError("ir_workspace must be an InfraredWorkspace object")
        if not isinstance(ir_plugin, InfraredPlugin):
            raise ValueError("ir_plugin must be an InfraredPlugin object")

        # Create ansible command
        ansible_cmd = ["ansible-playbook"] + cli_args

        # Run ansible command
        result = subprocess.run(ansible_cmd, check=True, capture_output=True)

        # Return ansible results
        return result.stdout.decode("utf-8")
    except subprocess.CalledProcessError as e:
        # Handle subprocess errors
        raise RuntimeError(f"Ansible command failed with exit code {e.returncode}")
    except ValueError as e:
        # Handle invalid input parameters
        raise ValueError(f"Invalid input parameter: {e}")

def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value
    return flatten_dict

def inject_config(self):
    if os.environ.get("CONFIG_PATH") is None:
        os.environ["CONFIG_PATH"] = "config.json"
    return os.environ["CONFIG_PATH"]

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError(f"Path {path} does not start with root {root}")
    return path[len(root):]
